+            }
+            """ },
+        { typeof(GrampsRepository), $$"""
+            {
+              "_class": "Repository", "handle": "r1", "gramps_id": "R0001", "change": 1793295509, "private": false,
+              "name": "State archive", "type": { "_class": "RepositoryType", "value": 1, "string": "" },
